function bsw_render_settings(){
 if(!current_user_can('manage_options'))return;
 if(isset($_POST['bsw_save_settings'])&&check_admin_referer('bsw_save_theme_settings')){
  $raw=wp_unslash($_POST['bsw']??array());$old=bsw_get_settings();$new=$old;
  $text=array('brand_name','tagline','registration_notice','login_welcome','home_intro','founder_collection_title');
  foreach($text as $k)if(isset($raw[$k]))$new[$k]=sanitize_text_field($raw[$k]);
  $new['home_intro']=sanitize_textarea_field($raw['home_intro']??$old['home_intro']);
  $new['accent']=sanitize_hex_color($raw['accent']??$old['accent'])?:'#202122';
  $new['login_background']=sanitize_hex_color($raw['login_background']??$old['login_background'])?:'#f8f9fa';
  $new['login_logo']=esc_url_raw($raw['login_logo']??'');
  $checks=array('show_header_search','show_sidebar','show_community_links','show_media_links','show_language_links','show_stats_links','show_topics','show_az','show_advanced_search','show_featured','show_random','show_entities','show_commons','show_article_submission','show_recent_changes','show_contributors','allow_registration','require_email','show_founders','show_article_tools','show_watchlist','show_edit_proposal','show_report','show_related','show_breadcrumbs','show_footer_menu','show_home_featured','show_home_recent','show_home_discovery','show_home_stats','show_home_contribute','email_notifications');
  foreach($checks as $k)$new[$k]=isset($raw[$k])?'1':'0';
  $new['items_per_page']=min(100,max(5,absint($raw['items_per_page']??20)));
  $role=sanitize_key($raw['registration_role']??'wiki_contributor');$new['registration_role']=in_array($role,array('subscriber','wiki_contributor'),true)?$role:'wiki_contributor';
  update_option('bsw_theme_settings',$new,false);
  echo '<div class="notice notice-success"><p>BIGSHOR Wiki settings saved.</p></div>';
 }
 $s=bsw_get_settings();
 echo '<div class="wrap bsw-admin"><h1>BIGSHOR Wiki Control Centre</h1><p>Manage the branding, front-end navigation, community features, account access and reader experience from one place.</p><form method="post">';wp_nonce_field('bsw_save_theme_settings');
 echo '<h2>Branding & appearance</h2><table class="form-table"><tr><th>Brand name</th><td><input class="regular-text" name="bsw[brand_name]" value="'.esc_attr($s['brand_name']).'"></td></tr><tr><th>Tagline</th><td><input class="regular-text" name="bsw[tagline]" value="'.esc_attr($s['tagline']).'"></td></tr><tr><th>Accent colour</th><td><input type="color" name="bsw[accent]" value="'.esc_attr($s['accent']).'"></td></tr><tr><th>Login logo URL</th><td><input class="regular-text" name="bsw[login_logo]" value="'.esc_attr($s['login_logo']).'" placeholder="https://..."><p class="description">Upload a logo to Media Library and paste its URL.</p></td></tr><tr><th>Login page background</th><td><input type="color" name="bsw[login_background]" value="'.esc_attr($s['login_background']).'"></td></tr><tr><th>Login welcome text</th><td><input class="regular-text" name="bsw[login_welcome]" value="'.esc_attr($s['login_welcome']).'"></td></tr></table>';
 echo '<h2>Front-end layout & navigation</h2><table class="form-table">';
 $labels=array('show_header_search'=>'Show header search','show_sidebar'=>'Show Explore sidebar','show_community_links'=>'Show community navigation','show_media_links'=>'Show media navigation','show_language_links'=>'Show language navigation','show_stats_links'=>'Show statistics navigation','show_footer_menu'=>'Show footer navigation','show_breadcrumbs'=>'Show breadcrumbs','show_topics'=>'Browse topics page','show_az'=>'A–Z index','show_advanced_search'=>'Advanced search','show_featured'=>'Featured articles','show_random'=>'Random article','show_entities'=>'Knowledge entities','show_commons'=>'BIGSHOR Commons gallery','show_article_submission'=>'Article submission','show_recent_changes'=>'Recent changes','show_contributors'=>'Contributor directory','show_article_tools'=>'Show article tools','show_related'=>'Show related articles','show_home_featured'=>'Homepage: featured knowledge','show_home_recent'=>'Homepage: recently updated','show_home_discovery'=>'Homepage: discovery section','show_home_stats'=>'Homepage: statistics','show_home_contribute'=>'Homepage: contribute card');
 foreach($labels as $k=>$label)echo '<tr><th>'.esc_html($label).'</th><td><label><input type="checkbox" name="bsw['.$k.']" value="1" '.checked($s[$k],'1',false).'> Enabled</label></td></tr>';
 echo '<tr><th>Articles per directory page</th><td><input type="number" min="5" max="100" name="bsw[items_per_page]" value="'.(int)$s['items_per_page'].'"></td></tr><tr><th>Homepage introduction</th><td><textarea class="large-text" rows="3" name="bsw[home_intro]">'.esc_textarea($s['home_intro']).'</textarea></td></tr></table>';
 echo '<h2>Community & editorial tools</h2><table class="form-table">';
 foreach(array('show_watchlist'=>'Watchlists','show_edit_proposal'=>'Suggest an edit','show_report'=>'Report an article','email_notifications'=>'Email notifications for watchlist updates') as $k=>$label)echo '<tr><th>'.esc_html($label).'</th><td><label><input type="checkbox" name="bsw['.$k.']" value="1" '.checked($s[$k],'1',false).'> Enabled</label></td></tr>';
 echo '</table><h2>Accounts & registration</h2><table class="form-table"><tr><th>Allow public registration</th><td><label><input type="checkbox" name="bsw[allow_registration]" value="1" '.checked($s['allow_registration'],'1',false).'> Enabled</label></td></tr><tr><th>New account role</th><td><select name="bsw[registration_role]"><option value="wiki_contributor" '.selected($s['registration_role'],'wiki_contributor',false).'>Wiki Contributor</option><option value="subscriber" '.selected($s['registration_role'],'subscriber',false).'>Reader (Subscriber)</option></select></td></tr><tr><th>Require email verification</th><td><label><input type="checkbox" name="bsw[require_email]" value="1" '.checked($s['require_email'],'1',false).'> Require verified email before login (verification workflow enabled)</label></td></tr><tr><th>Registration notice</th><td><input class="large-text" name="bsw[registration_notice]" value="'.esc_attr($s['registration_notice']).'"></td></tr></table>';
 echo '<h2>Founder collection</h2><table class="form-table"><tr><th>Show founder directory</th><td><label><input type="checkbox" name="bsw[show_founders]" value="1" '.checked($s['show_founders'],'1',false).'> Enabled</label></td></tr><tr><th>Directory title</th><td><input class="regular-text" name="bsw[founder_collection_title]" value="'.esc_attr($s['founder_collection_title']).'"></td></tr></table><p><button class="button button-primary" name="bsw_save_settings" value="1">Save BIGSHOR settings</button></p></form></div>';
}
function bsw_render_founder_admin(){
 if(!current_user_can('manage_options'))return;
 $count=(int)(wp_count_posts('wiki_article')->publish??0);$founders=get_posts(array('post_type'=>'wiki_article','post_status'=>array('publish','draft','pending'),'numberposts'=>-1,'meta_key'=>'_bsw_founder_profile','meta_value'=>'1','fields'=>'ids'));
 echo '<div class="wrap"><h1>BIGSHOR Founder Collection</h1><p>Import the curated set of 50 notable founder starter profiles. Entries are presented as a non-ranked editorial selection, with source links and review flags. Editors should re-check each source and expand the biographies before describing the collection as fully fact-checked.</p><p><strong>Founder profiles currently imported:</strong> '.count($founders).'</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('bsw_import_founders');echo '<input type="hidden" name="action" value="bsw_import_founders"><button class="button button-primary">Import / update 50 founder profiles</button></form><p><a href="'.esc_url(home_url('/founders/')).'" target="_blank">View public founder directory</a></p></div>';
}

/* Front-end account pages: branded login, registration, profile and password reset. */
function bsw_auth_url($slug){$p=get_page_by_path($slug);return $p?get_permalink($p):home_url('/'.$slug.'/');}
add_action('after_switch_theme',function(){
 $pages=array('login'=>array('Log in to BIGSHOR Wiki','[bigshor_login]'),'register'=>array('Create your BIGSHOR Wiki account','[bigshor_register]'),'account'=>array('My BIGSHOR Wiki account','[bigshor_account]'),'reset-password'=>array('Reset your password','[bigshor_reset_password]'),'founders'=>array('50 Notable Founders','[bigshor_founders_directory]'));
 foreach($pages as $slug=>$data)if(!get_page_by_path($slug))wp_insert_post(array('post_type'=>'page','post_status'=>'publish','post_name'=>$slug,'post_title'=>$data[0],'post_content'=>$data[1]));
});

add_action('admin_init',function(){if(!current_user_can('manage_options'))return;$pages=array('login'=>array('Log in to BIGSHOR Wiki','[bigshor_login]'),'register'=>array('Create your BIGSHOR Wiki account','[bigshor_register]'),'account'=>array('My BIGSHOR Wiki account','[bigshor_account]'),'reset-password'=>array('Reset your password','[bigshor_reset_password]'),'founders'=>array('50 Notable Founders','[bigshor_founders_directory]'));foreach($pages as $slug=>$data)if(!get_page_by_path($slug))wp_insert_post(array('post_type'=>'page','post_status'=>'publish','post_name'=>$slug,'post_title'=>$data[0],'post_content'=>$data[1]));});

add_action('login_init',function(){
 $action=sanitize_key(wp_unslash($_REQUEST['action']??'login'));
 if(in_array($action,array('register','lostpassword','retrievepassword'),true)){$target=$action==='register'?bsw_auth_url('register'):bsw_auth_url('reset-password');wp_safe_redirect($target);exit;}
 if($action==='rp'&&isset($_GET['key'],$_GET['login'])){$target=add_query_arg(array('key'=>sanitize_text_field(wp_unslash($_GET['key'])),'login'=>sanitize_user(wp_unslash($_GET['login']))),bsw_auth_url('reset-password'));wp_safe_redirect($target);exit;}
});
add_filter('login_url',function($url,$redirect,$force){return bsw_auth_url('login').($redirect?'?redirect_to='.rawurlencode($redirect):'');},10,3);
add_filter('register_url',function(){return bsw_auth_url('register');});
add_filter('lostpassword_url',function($url,$redirect){return bsw_auth_url('reset-password');},10,2);
add_filter('login_redirect',function($redirect,$requested,$user){if($user instanceof WP_User&&!user_can($user,'manage_options'))return bsw_auth_url('account');return $redirect;},10,3);
function bsw_auth_styles(){
 $s=bsw_get_settings();$logo=$s['login_logo'];$bg=$s['login_background'];
 echo '<style>body.login{background:'.esc_html($bg).';font-family:Inter,Arial,sans-serif}.login #login h1 a{'.($logo?'background-image:url('.esc_url($logo).');width:100%;height:75px;text-indent:-9999px;':'background-image:none;width:auto;height:auto;text-indent:0;color:#202122;font-size:21px;font-weight:800;text-decoration:none;'). 'background-size:contain}.login #loginform,.login #registerform,.login #lostpasswordform{border:1px solid #e5e7eb;border-radius:12px;box-shadow:0 12px 35px rgba(0,0,0,.06)}.login #nav a,.login #backtoblog a{color:#202122}.login .button-primary{background:#202122;border-color:#202122;text-shadow:none;box-shadow:none}.login .button-primary:hover{background:#444;border-color:#444}</style>';
}
add_action('login_enqueue_scripts','bsw_auth_styles');
add_filter('login_headertext',function(){return 'BIGSHOR Wiki';});
add_filter('login_headerurl',function(){return home_url('/');});
function bsw_auth_form_css(){return '<style>.bsw-auth{max-width:480px;margin:24px auto;padding:28px;border:1px solid #e5e7eb;border-radius:12px;background:#fff;box-shadow:0 8px 28px rgba(0,0,0,.04)}.bsw-auth h2{margin-top:0}.bsw-auth label{display:block;font-weight:600;margin:13px 0 5px}.bsw-auth input{width:100%;box-sizing:border-box;padding:12px;border:1px solid #c7cdd4;border-radius:6px;font:inherit}.bsw-auth button{background:#202122;color:#fff;border:0;padding:12px 18px;border-radius:6px;font-weight:700;cursor:pointer;margin-top:15px}.bsw-auth .bsw-auth-note{font-size:13px;color:#626b75}.bsw-auth .bsw-auth-error{background:#fff1f0;border-left:4px solid #c0392b;padding:10px;margin:12px 0}.bsw-auth .bsw-auth-success{background:#edf8f0;border-left:4px solid #26834a;padding:10px;margin:12px 0}</style>' ;}
add_shortcode('bigshor_login',function(){
 if(is_user_logged_in())return '<div class="bsw-auth">You are already signed in. <a href="'.esc_url(bsw_auth_url('account')).'">Open your account</a>.</div>'.bsw_auth_form_css();
 $msg='';if(isset($_POST['bsw_login_submit'])){
  if(!isset($_POST['bsw_login_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['bsw_login_nonce'])),'bsw_login'))$msg='<div class="bsw-auth-error">Security check failed. Refresh and try again.</div>';
  else{$creds=array('user_login'=>sanitize_text_field(wp_unslash($_POST['log']??'')),'user_password'=>(string)wp_unslash($_POST['pwd']??''),'remember'=>!empty($_POST['rememberme']));$user=wp_signon($creds,is_ssl());if(is_wp_error($user))$msg='<div class="bsw-auth-error">'.esc_html($user->get_error_message()).'</div>';else{$dest=isset($_GET['redirect_to'])?wp_validate_redirect(wp_unslash($_GET['redirect_to']),bsw_auth_url('account')):bsw_auth_url('account');wp_safe_redirect($dest);exit;}}
 }
 $s=bsw_get_settings();$out=bsw_auth_form_css().'<div class="bsw-auth"><h2>'.esc_html($s['login_welcome']).'</h2><p class="bsw-auth-note">Sign in to contribute, manage your watchlist and participate in the BIGSHOR Wiki community.</p>'.$msg.'<form method="post">'.wp_nonce_field('bsw_login','bsw_login_nonce',true,false).'<label for="bsw-user">Username or email</label><input id="bsw-user" name="log" autocomplete="username" required><label for="bsw-pass">Password</label><input id="bsw-pass" type="password" name="pwd" autocomplete="current-password" required><label><input style="width:auto" type="checkbox" name="rememberme" value="1"> Remember me</label><button name="bsw_login_submit" value="1">Log in</button></form><p><a href="'.esc_url(bsw_auth_url('reset-password')).'">Forgot password?</a> · <a href="'.esc_url(bsw_auth_url('register')).'">Create an account</a></p></div>';return $out;
});
add_shortcode('bigshor_register',function(){
 $s=bsw_get_settings();if($s['allow_registration']!=='1')return bsw_auth_form_css().'<div class="bsw-auth"><h2>Registration is closed</h2><p>New account creation is currently disabled.</p></div>';
 if(is_user_logged_in())return '<div class="bsw-auth">You are already signed in.</div>'.bsw_auth_form_css();$msg='';
 if(isset($_POST['bsw_register_submit'])){
  if(!isset($_POST['bsw_register_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['bsw_register_nonce'])),'bsw_register'))$msg='<div class="bsw-auth-error">Security validation failed.</div>';
  else{$username=sanitize_user(wp_unslash($_POST['username']??''),true);$email=sanitize_email(wp_unslash($_POST['email']??''));$pass=(string)wp_unslash($_POST['password']??'');$confirm=(string)wp_unslash($_POST['confirm_password']??'');
   if(strlen($username)<3||!validate_username($username))$msg='<div class="bsw-auth-error">Choose a valid username with at least 3 characters.</div>';
   elseif(!is_email($email))$msg='<div class="bsw-auth-error">Enter a valid email address.</div>';
   elseif(username_exists($username)||email_exists($email))$msg='<div class="bsw-auth-error">That username or email is already registered.</div>';
   elseif(strlen($pass)<10||!preg_match('/[A-Za-z]/',$pass)||!preg_match('/[0-9]/',$pass))$msg='<div class="bsw-auth-error">Use at least 10 characters, including letters and numbers.</div>';
   elseif($pass!==$confirm)$msg='<div class="bsw-auth-error">Passwords do not match.</div>';
   else{$uid=wp_create_user($username,$pass,$email);if(is_wp_error($uid))$msg='<div class="bsw-auth-error">'.esc_html($uid->get_error_message()).'</div>';else{$role=$s['registration_role']==='subscriber'?'subscriber':'wiki_contributor';$u=new WP_User($uid);$u->set_role($role);update_user_meta($uid,'_bsw_email_verified',$s['require_email']==='1'?'0':'1');if($s['require_email']==='1'){$token=wp_generate_password(32,false,false);update_user_meta($uid,'_bsw_verify_token',wp_hash_password($token));$link=add_query_arg(array('bsw_verify'=>$uid,'token'=>$token),bsw_auth_url('register'));wp_mail($email,'Verify your BIGSHOR Wiki account',"Welcome to BIGSHOR Wiki. Verify your email address using this link:\n\n".$link);$msg='<div class="bsw-auth-success">Account created. Check your email and follow the verification link before signing in.</div>';}else{$msg='<div class="bsw-auth-success">Your account has been created. <a href="'.esc_url(bsw_auth_url('login')).'">Log in now</a>.</div>';}}}
  }
 }
 if(isset($_GET['bsw_verify'],$_GET['token'])){$uid=absint($_GET['bsw_verify']);$token=sanitize_text_field(wp_unslash($_GET['token']));$hash=get_user_meta($uid,'_bsw_verify_token',true);if($hash&&wp_check_password($token,$hash)) {update_user_meta($uid,'_bsw_email_verified','1');delete_user_meta($uid,'_bsw_verify_token');$msg='<div class="bsw-auth-success">Email verified. You can now <a href="'.esc_url(bsw_auth_url('login')).'">log in</a>.</div>';}}
 $out=bsw_auth_form_css().'<div class="bsw-auth"><h2>Create a BIGSHOR Wiki account</h2><p class="bsw-auth-note">'.esc_html($s['registration_notice']).'</p>'.$msg.'<form method="post">'.wp_nonce_field('bsw_register','bsw_register_nonce',true,false).'<label>Username</label><input name="username" autocomplete="username" required minlength="3"><label>Email address</label><input type="email" name="email" autocomplete="email" required><label>Password</label><input type="password" name="password" autocomplete="new-password" required minlength="10"><label>Confirm password</label><input type="password" name="confirm_password" autocomplete="new-password" required><button name="bsw_register_submit" value="1">Create account</button></form><p>Already registered? <a href="'.esc_url(bsw_auth_url('login')).'">Log in</a>.</p></div>';return $out;
});
add_shortcode('bigshor_account',function(){if(!is_user_logged_in())return '<p>Please <a href="'.esc_url(bsw_auth_url('login')).'">log in</a> to view your account.</p>'; $u=wp_get_current_user();$out=bsw_auth_form_css().'<div class="bsw-auth"><h2>My BIGSHOR Wiki account</h2><p><strong>'.esc_html($u->display_name).'</strong><br>'.esc_html($u->user_email).'</p><ul><li><a href="'.esc_url(bsw_auth_url('my-watchlist')).'">My watchlist</a></li><li><a href="'.esc_url(bsw_auth_url('submit-article')).'">Submit an article</a></li><li><a href="'.esc_url(bsw_auth_url('recent-changes')).'">Recent changes</a></li></ul><p><a href="'.esc_url(wp_logout_url(home_url('/'))).'">Log out</a></p></div>';return $out;});
add_shortcode('bigshor_reset_password',function(){
 $msg='';if(isset($_POST['bsw_reset_request'])){if(!isset($_POST['bsw_reset_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['bsw_reset_nonce'])),'bsw_reset'))$msg='<div class="bsw-auth-error">Security check failed.</div>';else{$user=retrieve_password(sanitize_text_field(wp_unslash($_POST['user_login']??'')));$msg=is_wp_error($user)?'<div class="bsw-auth-error">Unable to process that request. Check the account details and try again.</div>':'<div class="bsw-auth-success">If the account exists, a password reset email has been sent.</div>';}}
 if(isset($_GET['key'],$_GET['login'])){$user=check_password_reset_key(sanitize_text_field(wp_unslash($_GET['key'])),sanitize_user(wp_unslash($_GET['login'])));if(is_wp_error($user))$msg='<div class="bsw-auth-error">This reset link is invalid or expired. Request a new one.</div>';elseif(isset($_POST['bsw_new_password'])){if(!isset($_POST['bsw_new_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['bsw_new_nonce'])),'bsw_new_password'))$msg='<div class="bsw-auth-error">Security check failed.</div>';else{$p=(string)wp_unslash($_POST['new_password']??'');if(strlen($p)<10)$msg='<div class="bsw-auth-error">Password must contain at least 10 characters.</div>';else{reset_password($user,$p);$msg='<div class="bsw-auth-success">Password updated. <a href="'.esc_url(bsw_auth_url('login')).'">Log in</a>.</div>';}}}if(!is_wp_error($user))$msg.='<form method="post">'.wp_nonce_field('bsw_new_password','bsw_new_nonce',true,false).'<label>New password</label><input type="password" name="new_password" minlength="10" required><button name="bsw_new_password" value="1">Set new password</button></form>';}
 return bsw_auth_form_css().'<div class="bsw-auth"><h2>Reset your password</h2>'.$msg.(!isset($_GET['key'])?'<form method="post">'.wp_nonce_field('bsw_reset','bsw_reset_nonce',true,false).'<label>Username or email address</label><input name="user_login" required><button name="bsw_reset_request" value="1">Send reset link</button></form>':'').'<p><a href="'.esc_url(bsw_auth_url('login')).'">Back to log in</a></p></div>';
});

/* Ensure protected accounts cannot sign in before their email is verified. */
add_filter('wp_authenticate_user',function($user){if($user instanceof WP_User&&get_user_meta($user->ID,'_bsw_email_verified',true)==='0')return new WP_Error('bsw_unverified','Please verify your email address using the link we sent you.');return $user;},20);

add_filter('retrieve_password_message',function($message,$key,$user_login,$user_data){$url=add_query_arg(array('key'=>$key,'login'=>$user_login),bsw_auth_url('reset-password'));return "Someone has requested a password reset for the following account on BIGSHOR Wiki:\n\nUsername: ".$user_login."\n\nTo reset your password, visit this address:\n\n".$url."\n\nIf this was a mistake, ignore this email.\n";},10,4);
